import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {decorateContent,cinema,socialIcons,footerArtwork} from './art-direction.mjs';

// The approved product brief is the content source; these templates generate the static pages.
const root = path.dirname(fileURLToPath(import.meta.url));
const demoTemplate = fs.readFileSync(path.join(root,'templates/demo.inc'),'utf8');
const modules = [
  {slug:'desk',name:'Registry Desk',verb:'Find the owner.',job:'Cross-runtime discovery & owner attestation',icon:'users',headline:'An inventory with people behind it.',desc:'Bring agent manifests and identity references into one ownership review. Preserve the source of every match, and put unresolved sponsorship where a person can inspect it.',focus:'Ownerless queue',items:['Keep deployments and runtime instances distinct','Separate the business sponsor from the technical owner','Confirm a candidate owner with a dated attestation'],input:'Approved agent manifest + identity exports',output:'Source-linked inventory and ownerless review queue'},
  {slug:'review',name:'Registry Review',verb:'Keep the date.',job:'Identity lifecycle & expirations',icon:'clock',headline:'Authority needs a review date.',desc:'Explore a lifecycle record for identity references, attestations, and expiration dates. Make the next review visible without implying that a past approval covers every future action.',focus:'Attestation review',items:['Record reviewer, scope, and policy context','Keep expiry and review dates visible','Flag changes for a fresh human decision'],input:'Identity reference + owner attestation',output:'Dated review and expiry record'},
  {slug:'proof',name:'Registry Proof',verb:'Trace the link.',job:'Privilege relationships & orphan detection',icon:'link',headline:'Every relationship needs a reason.',desc:'Trace the route from a deployment to a sponsor, principal, credential reference, and connected tool. Separate direct evidence from inferred matches and absent relationships.',focus:'Authority graph',items:['Inspect a principal and its connected role','Surface unattributed deployments and uncertain edges','Retain the source behind each privilege relationship'],input:'Matched records + source references',output:'Inspectable graph and evidence-gap view'},
  {slug:'signal',name:'Registry Signal',verb:'Make the decision.',job:'Recertification & revocation workflow',icon:'review',headline:'A change becomes a review.',desc:'Bring changed scope, expired attestations, and ownerless records to a human reviewer. Keep a proposed revocation request distinct from an executed access change.',focus:'Review docket',items:['Identify the relationship that needs attention','Give the reviewer its owner and source context','Draft the next step for the source-system operator'],input:'Expiry, ownership, or scope exception',output:'Human-reviewed next action'},
  {slug:'report',name:'Registry Report',verb:'Keep the evidence.',job:'Audit & security-review evidence packs',icon:'evidence',headline:'Evidence you can follow back.',desc:'Explore an evidence-pack direction that carries source IDs, review dates, ownership decisions, and unresolved gaps into a security review.',focus:'Evidence pack',items:['Preserve source references and confidence','Separate confirmed decisions from missing evidence','Prepare a proposed CSV record for review'],input:'Source context + review decisions',output:'Proposed evidence-pack structure'}
];
const iconPaths={
  users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6M21 20v-2a6 6 0 0 0-4-5.7"/>',
  clock:'<circle cx="12" cy="12" r="8.5"/><path d="M12 7v5l3 2"/>',
  link:'<path d="m10 14 4-4M8 16l-1 1a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0M16 8l1-1a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0"/>',
  review:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3h8v4H8zM8 14l3 3 5-6"/>',
  evidence:'<path d="M6 3h9l4 4v14H6zM15 3v5h4M9 12h7M9 16h5"/>',
  runtime:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="m7 10 3 2-3 2M13 15h4"/>',
  identity:'<rect x="3" y="5" width="18" height="14" rx="2"/><circle cx="8" cy="10" r="2"/><path d="M5 16v-1a3 3 0 0 1 6 0v1M14 9h4M14 13h4"/>',
  key:'<circle cx="8" cy="9" r="4"/><path d="m11 12 9 9M15 16l3-3M18 19l3-3"/>',
  scope:'<path d="M8 3H3v5M16 3h5v5M21 16v5h-5M8 21H3v-5M8 12h8M12 8v8"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  arrow:'<path d="M4 12h15M14 7l5 5-5 5"/>',
  chevron:'<path d="m7 10 5 5 5-5"/>',
  eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',
  email:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',
  reset:'<path d="M3 10a9 9 0 1 1 1 8M3 3v7h7"/>',
  lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>'
};
const icon=(name='arrow',cls='')=>`<svg class="ui-icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.arrow}</svg>`;
const commit=()=>'<svg class="commit-icon" viewBox="0 0 28 28" aria-hidden="true" fill="none"><g class="commit-base" stroke="currentColor" stroke-width="1.7"><rect x="2.5" y="4.5" width="10" height="16"/><rect x="5.6" y="8" width="3.8" height="9"/></g><g class="commit-plate"><rect x="15" y="4.5" width="10.5" height="16" fill="currentColor"/><path d="M18 9h4.5M18 13h4.5" class="plate-lines" stroke-width="1.5"/></g><path class="commit-trace" d="M15 23h10.5" stroke="currentColor" stroke-width="1.8"/></svg>';
const button=(label,href,style='primary')=>`<a class="btn ${style}" href="${href}"><span>${label}</span>${style==='primary'?commit():icon('arrow')}</a>`;
const textLink=(label,href)=>`<a class="text-link" href="${href}"><span>${label}</span>${icon('arrow')}</a>`;
const tag=(label,tone='')=>`<span class="tag ${tone}">${label}</span>`;
const field=(label,value,cls='')=>`<div class="record-field ${cls}"><span>${label}</span><strong>${value}</strong></div>`;
function nav(p){return `<header class="site-header"><div class="container nav"><a class="brand" href="${p}index.html" aria-label="OwnerStamp home"><img src="${p}assets/logo/ownerstamp-primary.svg" width="206" height="44" alt="OwnerStamp"></a><button type="button" class="menu-toggle" data-menu-toggle aria-expanded="false" aria-controls="site-navigation" aria-label="Open navigation"><span></span><span></span></button><nav id="site-navigation" class="nav-links" aria-label="Primary navigation" data-nav-links><div class="nav-group"><button class="nav-disclosure" data-menu="products" aria-expanded="false" aria-controls="menu-products">Products ${icon('chevron')}</button><div class="mega-menu" id="menu-products" hidden><div class="mega-intro"><p class="eyebrow">The OwnerStamp ledger</p><h2>Five jobs.<br>One authority chain.</h2><p>Discover the proposed Registry modules.</p>${textLink('Platform overview',p+'platform.html')}</div><div class="mega-products">${modules.map(m=>`<a href="${p}products/registry-${m.slug}.html">${icon(m.icon)}<span><b>${m.name}</b><small>${m.job}</small></span>${icon('arrow')}</a>`).join('')}</div><div class="mega-bottom">${tag('Proposed modules')}${textLink('Explore the synthetic workspace',p+'demo/index.html')}</div></div></div><div class="nav-group"><button class="nav-disclosure" data-menu="approach" aria-expanded="false" aria-controls="menu-approach">Approach ${icon('chevron')}</button><div class="compact-menu" id="menu-approach" hidden><a href="${p}problem.html"><b>The problem</b><small>Where ownership loses its context</small></a><a href="${p}solution.html"><b>The solution</b><small>A source-backed reconciliation workflow</small></a><a href="${p}use-cases.html"><b>Use cases</b><small>Access review, investigation, evidence</small></a></div></div><a href="${p}evaluation.html">Evaluation</a><div class="nav-group"><button class="nav-disclosure" data-menu="company" aria-expanded="false" aria-controls="menu-company">Company ${icon('chevron')}</button><div class="compact-menu" id="menu-company" hidden><a href="${p}company.html"><b>About OwnerStamp</b><small>Responsibility, made inspectable</small></a><a href="${p}trust.html"><b>Trust & data boundaries</b><small>Sources, uncertainty, and human review</small></a><a href="${p}contact.html"><b>Contact</b><small>Choose the right conversation</small></a></div></div><a class="nav-signin" href="${p}sign-in.html">Sign in</a>${button('Request a review',p+'request-review.html')}</nav></div><div class="reading-progress" aria-hidden="true"><span data-reading-progress></span></div></header>`;}
function footer(p){return `<footer class="footer" data-chapter><div class="container"><div class="footer-top"><a href="${p}index.html"><img src="${p}assets/logo/ownerstamp-inverse.svg" width="206" height="44" alt="OwnerStamp"></a><p>Map every agent to an owner,<br>credential, tool, and revocation path.</p>${textLink('Start a conversation',p+'contact.html')}${socialIcons()}</div><div class="footer-grid"><div><p class="eyebrow">A record of responsibility.</p><p class="footer-principle">People.<br>Authority.<br>Evidence.</p></div><div><h3>Explore</h3>${[['Problem','problem'],['Solution','solution'],['Platform','platform'],['Use cases','use-cases']].map(([n,r])=>`<a href="${p}${r}.html">${n}</a>`).join('')}</div><div><h3>Proposed products</h3>${modules.map(m=>`<a href="${p}products/registry-${m.slug}.html">${m.name}</a>`).join('')}</div><div><h3>Connect</h3>${[['Paid evaluation','evaluation'],['Inventory review','request-review'],['Request a demo','request-demo'],['Contact','contact'],['Sign in','sign-in']].map(([n,r])=>`<a href="${p}${r}.html">${n}</a>`).join('')}</div><div><h3>Company</h3><a href="${p}company.html">About OwnerStamp</a><a href="${p}trust.html">Trust & data boundaries</a><a href="${p}demo/index.html">Synthetic demo</a></div></div>${footerArtwork(p)}<div class="footer-bottom"><span>© 2026 OwnerStamp</span><span>Ownership. Authority. Evidence.</span><a href="#main">Back to top ${icon('arrow')}</a></div></div></footer>`;}
function layout(file,title,description,content,opts={}){
  const p=file.includes('/')?'../':'';
  const doc=`<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="${description}"><meta name="theme-color" content="#F6F2EC"><title>${title} — OwnerStamp</title><link rel="icon" href="${p}assets/logo/favicon.svg"><link rel="apple-touch-icon" href="${p}assets/logo/apple-touch-icon.png"><link rel="preload" href="${p}assets/fonts/Newsreader.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="${p}assets/vendor/lenis.css"><link rel="stylesheet" href="${p}styles.css"></head><body data-page="${file.replace('.html','').replace('/','-')}" ${opts.auth?'class="auth-page"':''}><a class="skip-link" href="#main">Skip to content</a>${opts.auth?'':nav(p)}<main id="main">${decorateContent(content,p)}</main>${opts.auth?'':footer(p)}<script src="${p}assets/vendor/gsap.min.js" defer></script><script src="${p}assets/vendor/ScrollTrigger.min.js" defer></script><script src="${p}assets/vendor/lenis.min.js" defer></script><script src="${p}site.js" defer></script><script src="${p}motion.js" defer></script></body></html>`;
  const withEntry=file==='index.html'?doc.replace('<header',fs.readFileSync(path.join(root,'templates/entry.inc'),'utf8')+'<header').replace('class="home-hero"','id="home-hero" tabindex="-1" class="home-hero"'):doc;
  const result=withEntry.replace('</head>',`<link rel="stylesheet" href="${p}visual.css"><link rel="stylesheet" href="${p}editorial.css"><link rel="stylesheet" href="${p}entry.css"></head>`).replaceAll('href="#product-proof"',file==='solution.html'?'href="platform.html#workspace"':'href="#product-proof"');
  fs.mkdirSync(path.dirname(path.join(root,file)),{recursive:true});fs.writeFileSync(path.join(root,file),result);
}
function heading(eyebrow,title,desc='',cls=''){return `<div class="section-head ${cls}"><p class="eyebrow">${eyebrow}</p><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>`;}
function chapter(id,cls,body){return `<section id="${id}" class="section ${cls}" data-chapter><div class="container">${body}</div></section>`;}
function closing(p='',title='Start with the question.<br>Keep the evidence.'){return chapter('next-step','closing',`<div class="closing-grid"><div><p class="eyebrow">Your next review starts here</p><h2>${title}</h2><p>Bring your ownership question and high-level system context. Begin with a redacted inventory review or a guided product walkthrough.</p><div class="actions">${button('Request a redacted inventory review',p+'request-review.html')}${button('Request a guided demo',p+'request-demo.html','secondary')}</div></div><div class="closing-mark" aria-hidden="true"><img src="${p}assets/logo/ownerstamp-mark.svg" alt="" width="220" height="220"></div></div>`);}
function faq(entries){return `<div class="faq-layout">${heading('Questions, answered','Clear before<br>you begin.')}<div class="faq-list">${entries.map(([q,a])=>`<details><summary>${q}<span class="accordion-icon" aria-hidden="true"></span></summary><p>${a}</p></details>`).join('')}</div></div>`;}
function sourceMatrix(){return `<div class="source-matrix"><div class="matrix-row matrix-head"><span>Source</span><span>Proposed input</span><span>Availability</span></div><div class="matrix-row"><b>${icon('identity')}Microsoft Entra</b><span>Identity export</span>${tag('Proposed evaluation','neutral')}</div><div class="matrix-row"><b>${icon('key')}AWS IAM</b><span>Cloud role export</span>${tag('Proposed evaluation','neutral')}</div><div class="matrix-row"><b>${icon('runtime')}Agent runtime</b><span>Approved manifest</span>${tag('Proposed evaluation','neutral')}</div><p class="fine">Exact formats and permissions are scoped in the evaluation. This matrix does not claim live or certified connectors.</p></div>`;}
function authorityRecord(){return `<div class="authority-record" data-record-object><div class="record-binding" aria-hidden="true"><i></i><i></i></div><div class="record-label"><span>OWNERSTAMP / AUTHORITY RECORD</span>${tag('Synthetic sample','neutral')}</div><div class="record-title"><div><span class="eyebrow">Agent deployment</span><h3>PO-Assist-07</h3></div>${icon('runtime')}</div><p class="record-context">Northstar Components · Production</p><div class="record-body">${field('Human sponsor','Maya Chen <small>Confirmation needed</small>','story-owner')}${field('Principal','demo-guid-001','story-principal')}${field('Credential reference','demo-po-assist role','story-role')}${field('Declared scope','Read purchase order status','story-scope')}${field('Attestation review','14 October 2026','story-attest')}</div><div class="record-evidence">${icon('evidence')}<span>Source: approved manifest · sample-v3</span></div></div>`;}
function graph(){return `<div class="graph-frame"><div class="visual-header"><b>Authority relationships</b>${tag('Synthetic sample','neutral')}</div><svg class="graph-lines" viewBox="0 0 600 510" preserveAspectRatio="none" fill="none" aria-hidden="true"><path d="M300 155V185M300 172H118V300M300 265V287H482V300M482 380V405H300V415" stroke="currentColor" stroke-width="1.4"/><path class="trace-line" d="M300 155V185M300 172H118V300M300 265V287H482V300M482 380V405H300V415" stroke="#6f2638" stroke-width="2"/></svg><div class="graph-node node-agent">${icon('runtime')}<b>PO-Assist-07</b><small>Deployment · source-linked</small></div><div class="graph-node node-principal">${icon('identity')}<b>demo-guid-001</b><small>Principal · sample reference</small></div><div class="graph-node node-owner">${icon('users')}<b>Maya Chen</b><small>Inferred sponsor · confirm</small></div><div class="graph-node node-role">${icon('key')}<b>demo-po-assist</b><small>Credential / role reference</small></div><div class="graph-node node-tool">${icon('scope')}<b>Purchase order lookup</b><small>Read status · declared scope</small></div><p class="graph-caption">Deployment → sponsor / principal → role → tool & scope</p></div>`;}
function ledger(){return `<div class="ledger" data-ledger><div class="ledger-rail"><span class="ledger-monogram">OS</span>${['runtime','review','evidence','users'].map((x,i)=>`<span class="rail-icon ${i===0?'active':''}" aria-hidden="true">${icon(x)}</span>`).join('')}</div><div class="ledger-content"><div class="ledger-top"><span>Workspace / Agent inventory</span>${tag('DEMO · Synthetic sample data','neutral')}</div><div class="ledger-heading"><div><h3>Agent ownership</h3><p>Northstar Components · fictional workspace</p></div><span class="avatar">MC</span></div><div class="ledger-stats"><div><small>Sample deployments</small><strong>8</strong></div><div><small>Ownerless</small><strong>3 <i>Needs review</i></strong></div><div><small>Attested</small><strong>3</strong></div><div><small>Review / expired</small><strong>2</strong></div></div><div class="ledger-columns"><div class="ledger-queue"><div class="queue-title">Review queue <span>03</span></div>${[['PO-Assist-07','Production · Maya Chen, unconfirmed'],['Support-Summary-11','Staging · unassigned'],['Data-Quality-09','Staging · unassigned']].map(([n,s],i)=>`<button type="button" class="queue-row ${i===0?'selected':''}" data-ledger-record="${i}" aria-pressed="${i===0}"><span class="queue-square">${icon('runtime')}</span><span><b>${n}</b><small>${s}</small></span>${icon('arrow')}</button>`).join('')}<div class="queue-note">${icon('users')}Ownership needs a human decision.</div></div><div class="ledger-detail"><div class="detail-heading"><h4 data-ledger-name>PO-Assist-07</h4>${tag('Owner confirmation needed','review')}</div><div class="ledger-tabs" role="tablist" aria-label="Record detail"><button id="ledger-tab-owner" type="button" role="tab" data-ledger-tab="ownership" aria-selected="true" aria-controls="ledger-panel-ownership">Ownership</button><button id="ledger-tab-authority" type="button" role="tab" data-ledger-tab="authority" aria-selected="false" aria-controls="ledger-panel-authority" tabindex="-1">Authority</button><button id="ledger-tab-evidence" type="button" role="tab" data-ledger-tab="evidence" aria-selected="false" aria-controls="ledger-panel-evidence" tabindex="-1">Evidence</button></div><div id="ledger-panel-ownership" role="tabpanel" aria-labelledby="ledger-tab-owner" data-ledger-panel="ownership">${field('Business sponsor','<span data-ledger-owner>Maya Chen · unconfirmed</span>')}${field('Technical owner','Platform engineering · sample')}${field('Attribution confidence','Inferred · human review required')}<div class="detail-source">${icon('evidence')}Approved agent manifest · sample-v3</div></div><div id="ledger-panel-authority" role="tabpanel" aria-labelledby="ledger-tab-authority" data-ledger-panel="authority" hidden>${field('Principal','demo-guid-001')}${field('Credential / role','demo-po-assist')}${field('Declared scope','Read purchase order status')}<div class="detail-source">${icon('key')}Scope remains attached to its source.</div></div><div id="ledger-panel-evidence" role="tabpanel" aria-labelledby="ledger-tab-evidence" data-ledger-panel="evidence" hidden>${field('Manifest reference','sample-v3 / PO-Assist-07')}${field('Review due','14 October 2026')}${field('Open evidence gap','Sponsor has not confirmed')}<div class="detail-source">${icon('evidence')}Synthetic sources · no live provider contacted.</div></div></div></div></div></div>`;}
function expiry(){return `<div class="expiry-view"><div class="visual-header"><b>Attestation lifecycle</b>${tag('Synthetic sample','neutral')}</div><div class="expiry-record"><span class="avatar">MC</span><div><b>Maya Chen</b><small>PO-Assist-07 · sponsor confirmation</small></div>${tag('Needs review','review')}</div><div class="date-line"><div><small>Source recorded</small><b>07 Oct</b></div><i></i><div class="date-focus"><small>Review due</small><b>14 Oct</b></div><i></i><div><small>Next decision</small><b>Human review</b></div></div>${field('Declared scope','Read purchase order status')}${field('Attestation state','Unconfirmed ownership')}<p class="visual-note">An expiry is a review signal. It does not execute a revocation.</p></div>`;}
function docket(){return `<div class="docket"><div class="visual-header"><b>Review docket / 001</b>${tag('Synthetic sample','neutral')}</div><div class="docket-alert">${icon('clock')}<div><b>Owner attestation expired</b><small>PO-Assist-07 · sample review state</small></div></div><ol class="decision-list"><li><span>01</span><div><b>Inspect the evidence</b><small>Source, declared scope, and owner reference</small></div></li><li><span>02</span><div><b>Assign a reviewer</b><small>Keep the accountable person visible</small></div></li><li><span>03</span><div><b>Draft the proposed next step</b><small>No automatic source-system action</small></div></li></ol><div class="draft-state">${icon('review')}Proposed revocation request ${tag('Not executed','review')}</div></div>`;}
function report(){return `<div class="report-stack"><div class="report-sheet"><div class="report-top">${icon('evidence')}<span>OWNERSTAMP / EVIDENCE RECORD</span></div><h3>Ownership review<br>evidence pack.</h3><p>PO-Assist-07 / Northstar Components</p>${field('Source reference','Manifest sample-v3')}${field('Principal reference','demo-guid-001')}${field('Relationship confidence','Inferred · confirmation needed')}${field('Open gap','Human sponsor not attested')}<div class="report-stamp">${tag('Synthetic sample','neutral')}<span>07 OCT 2026</span></div></div><div class="report-spine" aria-hidden="true"></div></div>`;}
function miniModule(m){const draws={desk:`<div class="mini-row"><i class="mini-avatar">MC</i><span>Maya Chen</span>${tag('Unconfirmed','review')}</div><div class="mini-row"><i class="mini-avatar empty">?</i><span>Owner not assigned</span>${tag('Review','neutral')}</div>`,review:`<div class="mini-date"><span>07<small>OCT</small></span><i></i><span>14<small>REVIEW DUE</small></span></div>`,proof:`<div class="mini-graph"><span>${icon('runtime')}</span><i></i><span>${icon('identity')}</span><i></i><span>${icon('users')}</span></div>`,signal:`<div class="mini-row">${icon('review')}<span>Review assigned</span><i class="mini-dot"></i></div><div class="mini-row muted">${icon('key')}<span>Proposed revocation</span><small>Draft</small></div>`,report:`<div class="mini-report"><b>Evidence record</b><i></i><i></i><i></i><span>SOURCE-LINKED / SYNTHETIC</span></div>`};return `<div class="module-art art-${m.slug}" aria-hidden="true">${draws[m.slug]}</div>`;}
function moduleCards(p=''){return `<div class="module-grid">${modules.map((m,i)=>`<article class="module-card"><div class="module-top"><span>0${i+1}</span>${icon(m.icon)}</div>${miniModule(m)}<p class="eyebrow">Proposed module</p><h3>${m.name}</h3><p>${m.job}.</p>${textLink('Explore '+m.name,p+'products/registry-'+m.slug+'.html')}</article>`).join('')}</div>`;}
function statsBand(){const stats=[['5','Proposed registry modules','Desk, Review, Proof, Signal, and Report cover the ownership review chain.'],['30','Day inventory pilot','A bounded paid review using agreed source extracts and synthetic walkthroughs.'],['3','Core ownership questions','Who owns it, what can it access, and when should authority be reviewed?'],['0','Live changes required','The first evaluation is read-only; revocation remains a human decision.']];return `<section class="section stats-band" id="proof-stats" data-chapter><div class="container stats-wrap"><div class="stats-intro"><p class="eyebrow">Measured without pretending traction</p><h2>Proof that stays inside the current brief.</h2><p>OwnerStamp should feel credible without inventing customers, testimonials, or live product claims. These numbers describe the proposed evaluation model and product architecture.</p></div><div class="stats-grid">${stats.map(([n,t,d],i)=>`<article class="stat-card"><span class="stat-index">0${i+1}</span><strong>${n}</strong><div><h3>${t}</h3><p>${d}</p></div></article>`).join('')}</div><div class="stats-art" aria-hidden="true"><span></span><i></i><b>OWNER / AUTHORITY / EVIDENCE</b></div></div></section>`;}
function story(){const parts=[['Bring the sources.','Start with an Entra export, AWS IAM export, and approved agent manifest. Keep the original source-system references.'],['Reconcile the relationship.','Match the deployment to candidate principal and role references. A name match is a clue, not proof.'],['Put a person behind it.','Distinguish business sponsor from technical owner. Ask a human to confirm the ownership edge.'],['Give authority a boundary.','Keep declared tool scope, approval context, and review date together. Make absent evidence visible.'],['Carry the evidence forward.','Prepare an inspectable next step. A proposed revocation remains a request for a human operator.']];return `<section class="section story-section" id="workflow" data-chapter data-story>${'<div class="container">'}${heading('02 / From source to decision','Trace the authority<br>behind the action.','Follow one sample deployment from fragmented sources to a human-reviewed record.')}<div class="story-grid"><div class="story-chapters">${parts.map(([t,d],i)=>`<article class="story-chapter" data-story-step="${i}"><span class="story-number">0${i+1}</span><div><h3>${t}</h3><p>${d}</p>${tag(['Agreed extracts','Candidate match','Human confirmation','Scoped review','Proposed action'][i],'neutral')}</div></article>`).join('')}</div><div class="story-visual">${authorityRecord()}<div class="story-caption"><span data-story-caption>01 / Source references</span><a href="#product-proof">Skip to product view ${icon('arrow')}</a></div><div class="story-progress" aria-hidden="true"><i data-story-progress></i></div></div></div></div></section>`;}
function pageHero(eyebrow,title,desc,visual='',p=''){return `<section class="page-hero ${visual?'with-visual':''}" data-chapter><div class="container"><p class="breadcrumb"><a href="${p}index.html">OwnerStamp</a><span>/</span>${eyebrow}</p><div class="page-hero-grid"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="lead">${desc}</p><div class="actions">${button('Request a redacted inventory review',p+'request-review.html')}${textLink('Explore the synthetic demo',p+'demo/index.html')}</div></div>${visual?`<div class="page-hero-art">${visual}</div>`:''}</div></div></section>`;}
const home=`<section class="home-hero" data-chapter><div class="container hero-grid"><div class="hero-copy"><p class="eyebrow"><span class="eyebrow-rule"></span>Agent ownership & authority</p><h1>Who owns<br>this agent<span class="ox-text">?</span></h1><p class="lead">Map every agent to an accountable owner, credential, connected tool, defined scope, and revocation path.</p><p class="hero-support">Keep the source evidence—and the uncertainty—in view.</p><div class="hero-actions">${button('Request a redacted inventory review','request-review.html')}${textLink('Explore the synthetic demo','demo/index.html')}</div><div class="hero-index"><span>People</span><i>/</i><span>Identities</span><i>/</i><span>Authority</span><i>/</i><span>Evidence</span></div></div><div class="hero-art"><img class="hero-object-image" src="assets/images/authority-object.webp" width="960" height="1200" alt="A layered authority record bound with a metal spine, the OwnerStamp visual metaphor" fetchpriority="high"><div class="artifact-caption"><span>01 / THE AUTHORITY RECORD</span><span>People → authority → evidence</span></div><div class="floating-reference ref-sponsor">${icon('users')}<span><small>Human sponsor</small><b>Maya Chen · unconfirmed</b></span></div><div class="floating-reference ref-source">${icon('evidence')}<span><small>Source context</small><b>Manifest / sample-v3</b></span>${tag('Synthetic','neutral')}</div><span class="hero-coordinate">OS / PO-ASSIST-07</span></div></div><div class="container hero-bottom"><p>Read-only reconciliation & attestation overlay</p><a href="#ownership-gap">Scroll to trace the record ${icon('arrow')}</a></div></section>
${chapter('boundaries','boundary-strip',`<div class="boundary-grid"><div>${icon('identity')}<span><b>Your IAM stays in place.</b><small>Start from agreed source extracts.</small></span></div><div>${icon('evidence')}<span><b>Every edge has context.</b><small>Source, confidence, and gaps stay visible.</small></span></div><div>${icon('users')}<span><b>The decision stays human.</b><small>No automatic issuance or revocation.</small></span></div></div>`)}
${statsBand()}
${chapter('ownership-gap','white',`<div class="split-intro">${heading('01 / The ownership gap','One deployment.<br>Disconnected records.')}<div><p class="lead">The agent manifest, identity principal, cloud role, and accountable people can describe the same deployment from different places.</p>${textLink('Understand the problem','problem.html')}</div></div><div class="gap-grid">${[['runtime','Deployment ↔ identity','Which principal or role belongs to this runtime deployment?'],['users','Agent ↔ people','Who sponsors it, who maintains it, and what needs confirmation?'],['scope','Scope ↔ evidence','Which tools and declared permissions can the available records support?']].map(([ic,t,d],i)=>`<article class="gap-card"><span class="large-icon">${icon(ic)}</span><span class="gap-index">0${i+1}</span><h3>${t}</h3><p>${d}</p><div class="gap-lines" aria-hidden="true"><i></i><span></span><i></i></div></article>`).join('')}</div>`)}
${cinema()}
${story()}
${chapter('product-proof','proof-section',`<div class="split-intro">${heading('03 / A reviewable workspace','The relationship.<br>The source. The gap.')}<div><p>Switch views on one sample record. The dashboard keeps ownership, authority, and evidence distinct, so uncertainty never disappears behind a status badge.</p>${textLink('Explore the platform','platform.html')}</div></div>${ledger()}<div class="proof-bottom"><span>Illustrative UI / synthetic sample records</span>${textLink('Open the synthetic workspace','demo/index.html')}</div>`)}
${chapter('products','products-section',`${heading('04 / Five proposed modules','One ledger.<br>Five jobs worth doing.','Registry Desk, Review, Proof, Signal, and Report are proposed module directions, each focused on a distinct part of the authority chain.')}${moduleCards()}`)}
${chapter('use-cases','white',`<div class="split-intro">${heading('05 / Built around the review','Start with a question<br>your team actually asks.')}<div>${textLink('Explore the use cases','use-cases.html')}</div></div><div class="usecase-grid">${[['01','Prepare an access review.','Bring sponsor, identity, declared scope, attestation, and source context into one sample record.','users'],['02','Investigate a changed scope.','Inspect which relationship changed, who owns it, and which evidence still needs confirmation.','scope'],['03','Assemble the evidence.','Show confirmed references, inferred edges, and open gaps in the same review.','evidence']].map(([n,t,d,ic])=>`<a class="usecase-card" href="use-cases.html"><span>${n} / ${icon(ic)}</span><h3>${t}</h3><p>${d}</p>${icon('arrow','case-arrow')}</a>`).join('')}</div>`)}
${chapter('source-fit','',`<div class="grid-2">${heading('06 / Across the source systems','Keep your systems.<br>Reconcile the context.','The proposed first evaluation starts with two identity systems and one runtime. Microsoft Entra already provides agent governance; the cross-runtime gap has to survive comparison.')}${sourceMatrix()}</div><div class="comparison-note">${icon('identity')}<p>OwnerStamp is designed as a reconciliation and attestation overlay. Existing identity providers remain the source of identity and access control.</p>${textLink('See the approach','solution.html')}</div>`)}
${chapter('evaluation','white',`<div class="evaluation-grid"><div>${heading('07 / A scoped paid evaluation','A bounded sample.<br>A concrete decision.','Test the useful gap with a 30-day inventory pilot. Keep scope, source handling, and the decision criteria explicit.')}${textLink('Review the evaluation scope','evaluation.html')}</div><article class="pilot-card"><div class="pilot-top"><span>30-day inventory pilot</span>${tag('Pricing hypothesis','neutral')}</div><div class="pilot-price">$4,000<span>fixed / USD</span></div><p>Entra export + AWS IAM export + approved agent manifest.</p><ul class="check-list"><li>${icon('check')}Manual reconciliation with source references</li><li>${icon('check')}Ownership and evidence-gap review</li><li>${icon('check')}A human-reviewed findings conversation</li></ul>${button('Request a redacted inventory review','request-review.html')}<p class="fine">Estimated pricing is a test hypothesis, not a quote or checkout. Later post-interview hypothesis: $1,500/month + $2 per governed agent/month.</p></article></div>`)}
${chapter('questions','',faq([['Does OwnerStamp replace our identity provider?','No. The initial direction is a read-only reconciliation and attestation overlay. Identity issuance and access changes remain with the source systems.'],['Which systems are included in the first evaluation?','The proposed scope is one Entra export, one AWS IAM export, and one approved agent manifest. Exact formats, permissions, and handling are agreed before an evaluation.'],['Does the demo change real access?','No. Every record is synthetic. Assignments, expiry states, and proposed revocation drafts remain local to the demo and reset without external actions.'],['Can we request a demo separately?','Yes. A guided walkthrough uses synthetic records and has its own request page. It is separate from the redacted inventory review and paid evaluation.']]))}
${closing()}`;
layout('index.html','Who owns this agent?','Map every agent to an owner, credential, tool, and revocation path.',home);

const problem=pageHero('The problem','A simple question.<br>A fragmented answer.','Who owns this agent—and what is it allowed to do? The answer can be split across manifests, principals, cloud roles, and people.',graph())+chapter('disconnected','white',`${heading('Three relationships to reconcile','Similar names<br>are not evidence.')}<div class="gap-grid">${[['Agent to identity','A runtime deployment and an identity principal are different entities. Preserve their source IDs before deciding they are related.','runtime'],['Identity to people','Business sponsor, technical maintainer, and initiating user are different roles. One name cannot silently stand in for all three.','users'],['Authority to evidence','Purpose, tool, scope, approval, and expiry need their own references. An absent source remains an evidence gap.','scope']].map(([t,d,ic],i)=>`<article class="gap-card"><span class="large-icon">${icon(ic)}</span><span class="gap-index">0${i+1}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div>`)+chapter('incumbent','',`<div class="grid-2">${heading('The existing baseline','Entra is already<br>in the conversation.','Microsoft Entra provides agent identity governance. OwnerStamp’s cross-runtime hypothesis has to remain useful after comparison with the buyer’s existing Entra workflow.')}<div class="quote-panel"><span class="quote-rule"></span><h3>What remains unresolved<br>across the systems?</h3><p>A review is useful when it can point to a discrepancy, its sources, its confidence, and the person who can resolve it.</p>${textLink('How reconciliation works','solution.html')}</div></div>`)+chapter('boundaries','white',`<div class="grid-2">${heading('Precise about the scope','Expose the missing link.<br>Keep its limits visible.')}<div class="principle-list"><div><b>Source-linked ≠ complete</b><p>The evidence is bounded by the records made available.</p></div><div><b>Inferred ≠ confirmed</b><p>A candidate relationship still needs human review.</p></div><div><b>Proposed ≠ executed</b><p>A revocation draft is not an access change.</p></div></div></div>`)+closing();
layout('problem.html','The ownership problem','Understand the agent, identity, owner, and evidence relationships that need reconciliation.',problem);
const solution=pageHero('The solution','Make the authority<br>chain inspectable.','A human-reviewed ledger for deployments, people, identity references, tools, declared scope, and evidence. Your IAM remains in place.',authorityRecord())+story()+chapter('principles','white',`<div class="split-intro">${heading('Working principles','Context travels<br>with the record.')}<p>Matching, attribution, approval, and verification are separate decisions. Keep each decision tied to its source and reviewer.</p></div><div class="gap-grid">${[['source','Preserve the original.','Keep source-system IDs and provenance attached to matched records.'],['users','Confirm the person.','Treat inferred sponsorship as a candidate edge until a person reviews it.'],['review','Prepare the next step.','Surface a reviewable request for the source-system owner to decide.']].map(([ic,t,d])=>`<article class="card">${icon(iconPaths[ic]?ic:'evidence')}<h3>${t}</h3><p>${d}</p></article>`).join('')}</div>`)+chapter('directions','',`${heading('Connected jobs','Five proposed<br>module directions.')}${moduleCards()}`)+closing();
layout('solution.html','The OwnerStamp approach','Read-only reconciliation, human attestation, source evidence, and reviewable next steps.',solution);
const platform=pageHero('Platform','One record.<br>Its whole context.','Keep deployment, human sponsor, technical owner, identity, credential reference, scope, attestation, and evidence visibly distinct.')+chapter('workspace','proof-section',`${heading('The operational view','Inspect the record<br>as a reviewer.')}${ledger()}<div class="proof-bottom"><span>Illustrative UI / synthetic sample records</span>${textLink('Open the synthetic demo','demo/index.html')}</div>`)+chapter('model','white',`<div class="grid-2">${heading('A relationship model','Follow the edge<br>back to its source.','Every relationship carries a reference and a confidence state. Missing attribution is an explicit state, not an invisible default.')}${graph()}</div>`)+chapter('confidence','',`<div class="split-intro">${heading('Confidence is part of the record','Know what the<br>record can support.')}<p>Preserve the distinction between a direct source reference, an inferred relationship, and an unconfirmed ownership gap.</p></div><div class="confidence-grid"><article>${tag('Source-linked','success')}<h3>A direct reference.</h3><p>A relationship supported by an available record reference. Coverage can still be incomplete.</p></article><article>${tag('Inferred','review')}<h3>A candidate match.</h3><p>A relationship proposed from the extracts that still needs human confirmation.</p></article><article>${tag('Unattributed','neutral')}<h3>A visible gap.</h3><p>No confirmed owner or supported edge. Keep it in the reviewer’s queue.</p></article></div>`)+chapter('coverage','white',`<div class="grid-2">${heading('Source coverage','A three-system<br>starting point.','Proposed evaluation inputs. No live connector availability or certified integration is implied.')}${sourceMatrix()}</div>`)+closing();
layout('platform.html','Platform','Explore the agent authority record, source model, confidence states, and synthetic workspace.',platform);
for (const [i,m] of modules.entries()){
  const p='../'; const visual={desk:ledger,review:expiry,proof:graph,signal:docket,report:report}[m.slug]();
  const steps=[['The input',m.input],['The review',m.items[1]],['The proposed output',m.output]];
  const page=pageHero(`Proposed module / 0${i+1}`,m.headline,m.desc,visual,p)+chapter('job','white',`<div class="grid-2">${heading(m.name,m.verb,`A proposed module focused on ${m.job.toLowerCase()}.`)}<div class="principle-list">${m.items.map((t,j)=>`<div><span class="list-number">0${j+1}</span><b>${t}</b></div>`).join('')}</div></div>`)+chapter('workflow','',`${heading('The review sequence','From the source<br>to a clear next step.')}<div class="process-grid">${steps.map(([t,d],j)=>`<article class="process-step"><span>0${j+1}</span><h3>${t}</h3><p>${d}</p>${icon(j===0?'identity':j===1?'review':'evidence')}</article>`).join('')}</div>`)+chapter('detail','proof-section',`<div class="grid-2">${heading('Illustrative product view',m.focus+'.','Synthetic sample records demonstrate the review state. They do not imply live source connections or real access changes.')}${m.slug==='desk'?authorityRecord():visual}</div>`)+chapter('scope','white',faq([['Is '+m.name+' a live product?','It is a proposed module direction. The first evaluation is a bounded reconciliation and ownership-review workflow, with scope agreed before any customer extract is transferred.'],['What is outside the first evaluation?','Live credential issuance, universal discovery, runtime enforcement, and automatic revocation are excluded. Source availability and exact formats must be scoped.'],['Can I see the record workflow?','Yes. The synthetic demo includes Inventory, Graph, Attestations, and Evidence views. Every transition stays inside the browser and can be reset.']]))+chapter('related','',`${heading('Continue the authority chain','Explore the next job.')}<div class="related-modules">${modules.filter(x=>x!==m).map(x=>`<a href="registry-${x.slug}.html">${icon(x.icon)}<span><b>${x.name}</b><small>${x.job}</small></span>${icon('arrow')}</a>`).join('')}</div>`)+closing(p);
  layout(`products/registry-${m.slug}.html`,`${m.name} · Proposed module`,m.job+'. '+m.desc,page);
}
const cases=[{label:'Access review',title:'Who is accountable<br>for this deployment?',desc:'An IAM reviewer needs the sponsor, principal, credential reference, declared scope, review date, and source trail in the same record.',visual:authorityRecord(),checks:['Confirm the human sponsor','Inspect identity and role references','Keep attestation and evidence gaps visible']},{label:'Scope investigation',title:'What changed—and<br>what supports it?',desc:'A security platform engineer investigates a changed identity or declared scope. Start from the record that changed and follow the relationships back to their sources.',visual:graph(),checks:['Compare the declared scope','Inspect the source behind the edge','Flag uncertain relationships for human review']},{label:'Evidence preparation',title:'Can the next reviewer<br>follow the decision?',desc:'An evidence view needs references, confidence, review dates, and the unresolved gaps. Preserve the chain that supports the finding.',visual:report(),checks:['Preserve source-system references','Separate confirmed and inferred relationships','Prepare a proposed evidence-pack structure']}];
const usecases=pageHero('Use cases','The review is<br>the real work.','Give IAM and security teams a concrete record to inspect: ownership, changed authority, and evidence preparation.')+cases.map((c,i)=>chapter('case-'+i,i%2?'':'white',`<div class="usecase-detail ${i%2?'reverse':''}"><div>${heading('0'+(i+1)+' / '+c.label,c.title,c.desc)}<ul class="check-list">${c.checks.map(t=>`<li>${icon('check')}${t}</li>`).join('')}</ul>${textLink('Explore '+modules[[0,2,4][i]].name,'products/registry-'+modules[[0,2,4][i]].slug+'.html')}</div><div>${c.visual}</div></div>`)).join('')+closing();
layout('use-cases.html','Use cases','Access reviews, scope investigations, and evidence preparation for IAM and security teams.',usecases);
const evaluation=pageHero('Paid evaluation','A small scope.<br>A useful answer.','A proposed 30-day inventory pilot tests whether a source-backed reconciliation finds a useful discrepancy beyond the existing Entra workflow.')+chapter('pilot','white',`<div class="evaluation-grid"><article class="pilot-card"><div class="pilot-top"><b>30-day inventory pilot</b>${tag('Pricing hypothesis','neutral')}</div><div class="pilot-price">$4,000<span>fixed / USD</span></div><p>One Entra export. One AWS IAM export.<br>One approved agent manifest.</p><ul class="check-list"><li>${icon('check')}Agreed redacted sample only</li><li>${icon('check')}Deterministic matching and manual review</li><li>${icon('check')}Source-backed ownership discrepancies</li><li>${icon('check')}Findings review and proposed evidence export</li></ul>${button('Request a redacted inventory review','request-review.html')}<p class="fine">Test hypothesis. Final price, scope, and handling require written agreement. No payment checkout.</p></article><div>${heading('Success criteria','Evidence before<br>expansion.','Compare the findings with the team’s existing identity-governance workflow.')}<div class="principle-list"><div><b>A named IAM sponsor.</b><p>Scope and redacted-source access agreed with the person responsible.</p></div><div><b>A useful discrepancy.</b><p>At least one ownership or privilege finding survives manual review.</p></div><div><b>A decision date.</b><p>Agree when to decide whether the reconciled view warrants further investment.</p></div><div><b>A comparison with Entra.</b><p>The cross-runtime gap must remain relevant after the incumbent workflow is considered.</p></div></div></div></div>`)+chapter('scope','',`<div class="grid-2">${heading('The initial boundary','Reconciliation first.<br>Agree the rest.')}<div>${sourceMatrix()}<p class="fine">Live credential issuance and automatic revocation are excluded. No exact permissions, retention, hosting, or security commitments are assumed.</p></div></div>`)+chapter('commercial','white',`<div class="grid-2">${heading('Later pricing hypothesis','Price the scope<br>after the evidence.','After buyer interviews only, a separate subscription hypothesis may be tested.')}<div class="subscription-note"><span>$1,500<small>/ month platform</small></span><b>+</b><span>$2<small>/ governed agent / month</small></span><p>Not a current offer or validated market rate.</p></div></div>`)+closing();
layout('evaluation.html','Paid evaluation','A proposed $4,000 fixed 30-day inventory pilot with explicit scope and decision criteria.',evaluation);
const trust=pageHero('Trust & data boundaries','Trust starts<br>with the source.','A useful review tells you what is known, what is inferred, and what remains missing. The decision stays with the accountable person.',report())+chapter('data','white',`${heading('Three boundaries','Keep the record<br>honest about its reach.')}<div class="confidence-grid"><article>${icon('evidence')}<h3>Synthetic demo data.</h3><p>Fictional entities and sample IDs are labeled in every demo view. Reset clears the local interaction state.</p></article><article>${icon('users')}<h3>Human review.</h3><p>Assignment, expiry, and proposed revocation illustrate the workflow. They do not change real source-system access.</p></article><article>${icon('lock')}<h3>Agreed source handling.</h3><p>An evaluation requires defined scope and documented handling before a customer extract is transferred. Public forms have no upload field.</p></article></div>`)+chapter('evidence','',`<div class="grid-2">${heading('Evidence has limits','Source-linked<br>does not mean complete.','Missing telemetry, uncertain ownership, and absent approval context remain explicit gaps. A record reflects only the sources made available.')}<div class="principle-list"><div><b>Preserve the ID.</b><p>Keep original principal, role, and manifest references.</p></div><div><b>Preserve the confidence.</b><p>Make source-linked, inferred, and unattributed states distinct.</p></div><div><b>Preserve the decision.</b><p>Keep the reviewer, scope, date, and proposed next action together.</p></div></div></div>`)+chapter('questions','white',faq([['Are certifications or live integrations claimed?','No certifications, provider endorsements, or live connector availability are presented. Names such as Microsoft Entra and AWS identify proposed source inputs and existing systems.'],['Will a revocation draft change access?','No. The synthetic demo only drafts a local state. The proposed workflow leaves real changes to a human source-system operator.'],['What should we establish before a source extract is shared?','Agree the data scope, source permissions, handling, retention, and relevant security requirements before transferring an extract.']]))+closing();
layout('trust.html','Trust & data boundaries','Source evidence, human decisions, synthetic demo boundaries, and agreed evaluation handling.',trust);
const company=pageHero('Company','Responsibility,<br>made inspectable.','OwnerStamp focuses on the human accountability chain behind agent deployments: people, identity references, tools, authority, and evidence.')+chapter('mission','white',`<div class="company-statement"><p class="eyebrow">Our mission</p><h2>Reconcile fragmented inventories.<br><span>Make ownerless and over-scoped<br>agents visible before review.</span></h2></div>`)+chapter('principles','',`<div class="grid-2">${heading('The working principle','A clear record.<br>A named person.','An auditable accountability chain across identity systems and agent runtimes, without pretending there is one universal identity standard.')}<div class="principle-list"><div><span>01</span><b>Preserve source context.</b><p>Every useful relationship can be followed back.</p></div><div><span>02</span><b>Keep uncertainty visible.</b><p>A gap belongs in the review, not behind a polished badge.</p></div><div><span>03</span><b>Leave the decision human.</b><p>Reconciliation provides context for accountable action.</p></div></div></div>`)+chapter('audience','white',`${heading('Who the review serves','IAM leadership.<br>Security platform teams.')}<div class="audience-grid"><article class="card">${icon('users')}<h3>The IAM reviewer</h3><p>Needs to connect an agent with its sponsor, principal, credential reference, and scope before recertification.</p></article><article class="card">${icon('runtime')}<h3>The technical champion</h3><p>Needs inspectable source relationships and clear exceptions across Entra, cloud identities, and the agent runtime.</p></article></div>`)+closing();
layout('company.html','About OwnerStamp','OwnerStamp’s mission: make the human accountability chain behind agent deployments inspectable.',company);
const contact=pageHero('Contact','Start with<br>your question.','Choose the conversation that fits the work: a redacted inventory review or a guided walkthrough of the synthetic product workflow.')+chapter('routes','white',`<div class="contact-routes"><article class="contact-route"><span class="route-number">01</span>${icon('evidence') }<h2>Review your<br>inventory question.</h2><p>Share high-level system context and the ownership or privilege question you need to answer. Redacted extracts are handled only after scope is agreed.</p>${button('Request a redacted inventory review','request-review.html')}</article><article class="contact-route"><span class="route-number">02</span>${icon('runtime')}<h2>See the workflow<br>with a guide.</h2><p>Walk through ownership, identity relationships, attestation, and evidence gaps using synthetic records. No source-system connection is required.</p>${button('Request a guided demo','request-demo.html')}</article></div>`)+chapter('self-guided','',`<div class="grid-2">${heading('Explore at your pace','Follow a sample<br>record yourself.','The synthetic workspace has Inventory, Graph, Attestations, and Evidence views, with local review states and a reset control.')}<div class="contact-demo">${icon('runtime')}${textLink('Open the synthetic workspace','demo/index.html')}</div></div>`);
layout('contact.html','Contact','Choose an inventory review, guided demo, or self-guided synthetic workspace.',contact);
const formField=(id,label,type='text',wide=false,options='')=>`<div class="field ${wide?'wide':''}"><label for="${id}">${label}</label>${type==='textarea'?`<textarea id="${id}" name="${id}" rows="4" ${options}></textarea>`:type==='select'?`<select id="${id}" name="${id}" ${options}>${['Choose a range','1–10 deployments','11–50 deployments','51–200 deployments','More than 200','Not sure yet'].map((x,i)=>`<option value="${i?x:''}">${x}</option>`).join('')}</select>`:`<input id="${id}" name="${id}" type="${type}" ${options}>`}</div>`;
for (const kind of ['review','demo']){
 const isReview=kind==='review'; const label=isReview?'Inventory review':'Guided demo';
 const form=`<section class="intake-section" data-chapter><div class="container intake-grid"><div class="intake-copy"><p class="breadcrumb"><a href="index.html">OwnerStamp</a><span>/</span>${label}</p><p class="eyebrow">${label}</p><h1>${isReview?'Bring the question.<br>Start with context.':'See the record.<br>Follow the decision.'}</h1><p class="lead">${isReview?'Tell us which ownership or privilege relationship your team needs to understand. Begin with high-level scope.':'Request a walkthrough shaped around your review questions. We’ll use synthetic records to explore ownership, authority, and evidence.'}</p><div class="intake-topics">${(isReview?[['identity','Your source systems','Entra, cloud identities, and agent runtime context.'],['users','Your review question','Ownership, scope, attestation, or evidence gaps.'],['evidence','A bounded next step','Agree scope before any redacted extracts are shared.']]:[['users','Ownership','Sponsor and technical owner, including uncertain matches.'],['link','Identity relationships','Principal, credential reference, tool, and declared scope.'],['evidence','The decision trail','Source labels, expiry, gaps, and proposed next steps.']]).map(([ic,t,d])=>`<div>${icon(ic)}<span><b>${t}</b><small>${d}</small></span></div>`).join('')}</div><p class="intake-alt">${isReview?'Prefer a walkthrough first?':'Have a specific inventory question?'} ${textLink(isReview?'Request a guided demo':'Request an inventory review',isReview?'request-demo.html':'request-review.html')}</p></div><form class="form-shell" data-form="${isReview?'inventory-review':'guided-demo'}" novalidate><div class="form-heading"><span class="form-number">${isReview?'REVIEW / 01':'DEMO / 02'}</span><h2>${isReview?'Request an inventory review':'Request a guided demo'}</h2><p>Fields marked * are required.</p></div><div class="form-grid">${formField('name','Full name *','text',false,'autocomplete="name" required')}${formField('email','Work email *','email',false,'autocomplete="email" required')}${formField('organization','Organization *','text',false,'autocomplete="organization" required')}${formField('role','Role','text',false,'autocomplete="organization-title"')}${isReview?formField('scale','Approximate agent scope','select')+formField('systems','Relevant systems','text',false,'placeholder="Entra, AWS, internal runtime"'):formField('interest','Product interest','text',true,'placeholder="Ownership, lifecycle, graph, or evidence"')}${formField('question',isReview?'What question are you trying to answer?':'What would you like to see?','textarea',true)}<div class="field-error wide" data-form-error role="alert" hidden></div></div><p class="form-context">Share high-level context only. Keep credentials, secrets, and confidential records out of this form.</p><button class="btn primary form-submit" type="submit"><span>${isReview?'Request an inventory review':'Request a guided demo'}</span>${commit()}</button></form></div></section>`;
 layout(`request-${kind}.html`,`Request a ${kind==='review'?'redacted inventory review':'guided demo'}`,isReview?'Request a redacted inventory review with your system context and ownership question.':'Request a guided walkthrough of the OwnerStamp ownership, authority, and evidence workflow.',form+chapter('prepare','white',`<div class="grid-2">${heading('A focused conversation','Bring context.<br>Keep the sources scoped.')}<p>${isReview?'An inventory review tests whether a useful cross-runtime discrepancy remains after comparison with the team’s existing workflow. Source extracts are a separate, agreed step.':'A guided walkthrough explores synthetic inventory, relationship graph, attestation, and evidence states. It is separate from the scoped paid evaluation.'}</p></div>`));
}
const auth=`<section class="auth-layout" data-chapter><div class="auth-form-side"><a class="brand" href="index.html"><img src="assets/logo/ownerstamp-primary.svg" width="206" height="44" alt="OwnerStamp"></a><div class="auth-content"><p class="eyebrow">Your OwnerStamp workspace</p><h1>Welcome back.</h1><p>Sign in to continue your ownership review.</p><form data-form="sign-in" novalidate><div class="form-grid">${formField('email','Work email','email',true,'autocomplete="username" required')}<div class="field wide"><label for="password">Password</label><div class="password-field"><input id="password" name="password" type="password" autocomplete="current-password" required><button type="button" data-password-toggle aria-label="Show password" aria-pressed="false">${icon('eye')}</button></div></div><div class="field-error wide" data-form-error role="alert" hidden></div></div><div class="auth-options"><label><input type="checkbox" name="remember">Remember me</label><a href="contact.html">Need sign-in help?</a></div><button class="btn primary form-submit" type="submit"><span>Sign in</span>${commit()}</button></form><p class="auth-access">Need workspace access? <a href="request-review.html">Request a review</a></p></div><a class="auth-back" href="index.html">${icon('arrow')}Back to OwnerStamp</a></div><aside class="auth-brand-side"><p class="eyebrow">People / Authority / Evidence</p><h2>Know who<br>stands behind<br>the record.</h2>${authorityRecord()}<p>Review the relationship,<br>not just the identity.</p></aside></section>`;
layout('sign-in.html','Sign in','Sign in to your OwnerStamp workspace.',auth,{auth:true});
// Keep the isolated synthetic workspace's fixture behavior and source data.
layout('demo/index.html','Synthetic demo workspace','Explore OwnerStamp using resettable fictional agent records.',demoTemplate);
console.log('Built 18 OwnerStamp pages from the approved content and identity.');
